contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 otherNonce
    ) public {
        address[] memory empty = new address[](0);
        C.ERC20Asset[] memory noErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory noErc721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(0x1),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: empty,
            floorTokens: empty,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        bytes32 h = c.hashOrder(order);
        require(!c.cancelledOrders(h));

        C.Order memory other = order;
        other.nonce = otherNonce;
        bytes32 h2 = c.hashOrder(other);
        require(!c.cancelledOrders(h2));

        c.cancel(order);

        assert(c.cancelledOrders(h) && !c.cancelledOrders(h2));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newFee) public {
        require(newFee < 1000);
        uint256 before = c.fee();
        bool reverted;
        if (newFee < 30) {
            c.setFee(newFee);
            reverted = false;
        } else {
            try c.setFee(newFee) { reverted = false; } catch { reverted = true; }
        }
        if (newFee < 30) {
            assert(!reverted && c.fee() == newFee);
        } else {
            assert(reverted && c.fee() == before);
        }
    }
}

