        bytes32 h = c.hashOrder(order);

        bytes32 typeHash = c.ORDER_TYPE_HASH();
        bytes32 ds = c.domainSeparatorV4();
        bytes32 emptyHash = keccak256("");
        bytes32 structHash = keccak256(
            abi.encode(
                typeHash,
                maker,
                isCall,
                isLong,
                baseAsset,
                strike,
                premium,
                duration,
                expiration,
                nonce,
                emptyHash,
                emptyHash,
                keccak256(c.encodeERC20Assets(order.erc20Assets)),
                keccak256(c.encodeERC721Assets(order.erc721Assets))
            )
        );
        bytes32 expected = keccak256(abi.encodePacked("\x19\x01", ds, structHash));

        assert(h == expected);
    }
    receive() external payable {}
}

