    constructor(C _c) { c = _c; }
    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        C.Order memory order;
        order.maker = address(this);
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        c.cancel(order);

        assert(c.cancelledOrders(c.hashOrder(order)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory uri) public payable {
        require(bytes(uri).length < 100);
        c.setBaseURI(uri);
        assert(keccak256(bytes(c.baseURI())) == keccak256(bytes(uri)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes4 interfaceId) public payable {
        bool result = c.supportsInterface(interfaceId);
        bool expected = interfaceId == 0x01ffc9a7 || interfaceId == 0x80ac58cd || interfaceId == 0x5b5e139f;
        assert(result == expected);
    }
    receive() external payable {}
}
